  1→/**
  2→ * Public API endpoint — joins a customer to the waitlist from the storefront widget.
  3→ *
  4→ * Called from the theme app extension block when a zip code check fails and
  5→ * the merchant has enabled the waitlist feature.
  6→ *
  7→ * POST /api/waitlist
  8→ * Body: { shop: string, zip: string, email: string }
  9→ *
 10→ * Response:
 11→ *   200 { success: true, message: "..." }
 12→ *   400 { error: "..." }
 13→ *   500 { error: "..." }
 14→ */
 15→import type { ActionFunctionArgs, LoaderFunctionArgs } from "react-router";
 16→import db from "../db.server";
 17→import { getShopSubscription } from "../billing.server";
 18→
 19→/**
 20→ * Normalize postal/zip code for multi-format international support.
 21→ * Handles: US ZIP+4, UK postcodes, Indian pincodes, Australian postcodes, Canadian postal codes.
 22→ */
 23→function normalizeZipCode(raw: string): string {
 24→  let z = raw.trim().toUpperCase();
 25→  z = z.replace(/\s+/g, "");        // collapse all internal spaces (UK: SW1A 2AA → SW1A2AA)
 26→  z = z.replace(/-\d{4}$/, "");     // strip US ZIP+4 suffix (90210-1234 → 90210)
 27→  return z;
 28→}
 29→
 30→const CORS_HEADERS = {
 31→  "Access-Control-Allow-Origin": "*",
 32→  "Access-Control-Allow-Methods": "POST, OPTIONS",
 33→  "Access-Control-Allow-Headers": "Content-Type",
 34→  "Content-Type": "application/json",
 35→};
 36→
 37→// Handle CORS preflight
 38→export const loader = async ({ request }: LoaderFunctionArgs) => {
 39→  if (request.method === "OPTIONS") {
 40→    return new Response(null, { status: 204, headers: CORS_HEADERS });
 41→  }
 42→  return new Response(JSON.stringify({ error: "Method not allowed" }), {
 43→    status: 405,
 44→    headers: CORS_HEADERS,
 45→  });
 46→};
 47→
 48→export const action = async ({ request }: ActionFunctionArgs) => {
 49→  if (request.method === "OPTIONS") {
 50→    return new Response(null, { status: 204, headers: CORS_HEADERS });
 51→  }
 52→
 53→  if (request.method !== "POST") {
 54→    return new Response(JSON.stringify({ error: "Method not allowed" }), {
 55→      status: 405,
 56→      headers: CORS_HEADERS,
 57→    });
 58→  }
 59→
 60→  let shop: string | null = null;
 61→  let zip: string | null = null;
 62→  let email: string | null = null;
 63→  let name: string | null = null;
 64→
 65→  try {
 66→    const body = await request.json();
 67→    shop = body?.shop ?? null;
 68→    zip = body?.zip ?? null;
 69→    email = body?.email ?? null;
 70→    name = body?.name ?? null;
 71→  } catch {
 72→    return new Response(JSON.stringify({ error: "Invalid JSON body" }), {
 73→      status: 400,
 74→      headers: CORS_HEADERS,
 75→    });
 76→  }
 77→
 78→  if (!shop || !zip || !email) {
 79→    return new Response(
 80→      JSON.stringify({ error: "Missing required fields: shop, zip, email" }),
 81→      { status: 400, headers: CORS_HEADERS },
 82→    );
 83→  }
 84→
 85→  // Validate shop is a real myshopify.com domain (prevents cross-shop enumeration)
 86→  if (!/^[a-zA-Z0-9][a-zA-Z0-9-]*\.myshopify\.com$/.test(shop) || shop.length > 100) {
 87→    return new Response(
 88→      JSON.stringify({ error: "Invalid shop parameter" }),
 89→      { status: 400, headers: CORS_HEADERS },
 90→    );
 91→  }
 92→
 93→  // Enforce input length limits to prevent abuse
 94→  if (zip.length > 20 || email.length > 254) {
 95→    return new Response(
 96→      JSON.stringify({ error: "Invalid input" }),
 97→      { status: 400, headers: CORS_HEADERS },
 98→    );
 99→  }
100→
101→  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
102→    return new Response(
103→      JSON.stringify({ error: "Invalid email address" }),
104→      { status: 400, headers: CORS_HEADERS },
105→    );
106→  }
107→
108→  // Check if shop's plan allows waitlist
109→  try {
110→    const subscription = await getShopSubscription(shop);
111→    if (subscription.limits.maxWaitlist === 0) {
112→      return new Response(
113→        JSON.stringify({ error: "Waitlist is not available on this store's plan" }),
114→        { status: 400, headers: CORS_HEADERS },
115→      );
116→    }
117→    // Enforce entry limit for Starter plan
118→    if (subscription.limits.maxWaitlist !== Infinity) {
119→      const currentCount = await db.waitlistEntry.count({ where: { shop } });
120→      if (currentCount >= subscription.limits.maxWaitlist) {
121→        return new Response(
122→          JSON.stringify({ error: "Waitlist is currently full. Please try again later." }),
123→          { status: 400, headers: CORS_HEADERS },
124→        );
125→      }
126→    }
127→  } catch {
128→    // Non-fatal — allow waitlist signup if subscription check fails
129→  }
130→
131→  try {
132→    await db.waitlistEntry.upsert({
133→      where: {
134→        shop_email_zipCode: {
135→          shop,
136→          email,
137→          zipCode: normalizeZipCode(zip),
138→        },
139→      },
140→      create: {
141→        shop,
142→        email,
143→        name: name ? name.trim().substring(0, 100) : null,
144→        zipCode: normalizeZipCode(zip),
145→        status: "waiting",
146→      },
147→      update: {
148→        status: "waiting",
149→      },
150→    });
151→
152→    return new Response(
153→      JSON.stringify({
154→        success: true,
155→        message: "You've been added to the waitlist!",
156→      }),
157→      { status: 200, headers: CORS_HEADERS },
158→    );
159→  } catch {
160→    return new Response(
161→      JSON.stringify({ error: "Failed to join waitlist. Please try again." }),
162→      { status: 500, headers: CORS_HEADERS },
163→    );
164→  }
165→};
