  1→// Shared plan constants — safe for both client and server
  2→
  3→export const PLAN_FREE = "free";
  4→export const PLAN_STARTER_MONTHLY = "Starter Monthly";
  5→export const PLAN_STARTER_ANNUAL = "Starter Annual";
  6→export const PLAN_PRO_MONTHLY = "Pro Monthly";
  7→export const PLAN_PRO_ANNUAL = "Pro Annual";
  8→export const PLAN_ULTIMATE_MONTHLY = "Ultimate Monthly";
  9→export const PLAN_ULTIMATE_ANNUAL = "Ultimate Annual";
 10→
 11→export const ALL_PAID_PLANS = [
 12→  PLAN_STARTER_MONTHLY,
 13→  PLAN_STARTER_ANNUAL,
 14→  PLAN_PRO_MONTHLY,
 15→  PLAN_PRO_ANNUAL,
 16→  PLAN_ULTIMATE_MONTHLY,
 17→  PLAN_ULTIMATE_ANNUAL,
 18→];
 19→
 20→export type PlanTier = "free" | "starter" | "pro" | "ultimate";
 21→
 22→export interface PlanLimits {
 23→  maxZipCodes: number;
 24→  allowBlocked: boolean;
 25→  maxDeliveryRules: number;
 26→  maxWaitlist: number;
 27→  csvImport: boolean;
 28→  csvExport: boolean;
 29→  widgetFullCustom: boolean;
 30→  showEtaCodReturn: boolean;
 31→  cartBlocking: boolean;
 32→  customCss: boolean;
 33→  apiAccess: boolean;
 34→  label: string;
 35→}
 36→
 37→export const PLAN_LIMITS: Record<PlanTier, PlanLimits> = {
 38→  free: {
 39→    maxZipCodes: 20,
 40→    allowBlocked: false,
 41→    maxDeliveryRules: 0,
 42→    maxWaitlist: 0,
 43→    csvImport: false,
 44→    csvExport: false,
 45→    widgetFullCustom: false,
 46→    showEtaCodReturn: false,
 47→    cartBlocking: false,
 48→    customCss: false,
 49→    apiAccess: false,
 50→    label: "Free",
 51→  },
 52→  starter: {
 53→    maxZipCodes: 500,
 54→    allowBlocked: false,
 55→    maxDeliveryRules: 3,
 56→    maxWaitlist: 25,
 57→    csvImport: true,
 58→    csvExport: false,
 59→    widgetFullCustom: true,
 60→    showEtaCodReturn: true,
 61→    cartBlocking: false,
 62→    customCss: false,
 63→    apiAccess: false,
 64→    label: "Starter",
 65→  },
 66→  pro: {
 67→    maxZipCodes: Infinity,
 68→    allowBlocked: true,
 69→    maxDeliveryRules: Infinity,
 70→    maxWaitlist: Infinity,
 71→    csvImport: true,
 72→    csvExport: true,
 73→    widgetFullCustom: true,
 74→    showEtaCodReturn: true,
 75→    cartBlocking: true,
 76→    customCss: false,
 77→    apiAccess: false,
 78→    label: "Pro",
 79→  },
 80→  ultimate: {
 81→    maxZipCodes: Infinity,
 82→    allowBlocked: true,
 83→    maxDeliveryRules: Infinity,
 84→    maxWaitlist: Infinity,
 85→    csvImport: true,
 86→    csvExport: true,
 87→    widgetFullCustom: true,
 88→    showEtaCodReturn: true,
 89→    cartBlocking: true,
 90→    customCss: true,
 91→    apiAccess: true,
 92→    label: "Ultimate",
 93→  },
 94→};
 95→
 96→export function getPlanTier(planName: string): PlanTier {
 97→  if (planName === PLAN_STARTER_MONTHLY || planName === PLAN_STARTER_ANNUAL)
 98→    return "starter";
 99→  if (planName === PLAN_PRO_MONTHLY || planName === PLAN_PRO_ANNUAL)
100→    return "pro";
101→  if (planName === PLAN_ULTIMATE_MONTHLY || planName === PLAN_ULTIMATE_ANNUAL)
102→    return "ultimate";
103→  return "free";
